import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

const Signup = (props) => {
  const [credentials, setCredentials] = useState({
    name: "",
    email: "",
    password: "",
    cpassword: "",
  });
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validation checks
    if (credentials.password !== credentials.cpassword) {
      props.showAlert("Passwords do not match", "danger");
      return;
    }

    if (credentials.password.length < 5) {
      props.showAlert("Password must be at least 5 characters long", "danger");
      return;
    }

    if (credentials.name.length < 3) {
      props.showAlert("Name must be at least 3 characters long", "danger");
      return;
    }

    setLoading(true);

    try {
      const { name, email, password } = credentials;
      const response = await fetch("http://localhost:5000/api/auth/createuser", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          name,
          email,
          password,
        }),
      });

      // Check if response is ok
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const json = await response.json();
      console.log('Signup response:', json);
      
      if (json.success) {
        // Handle both possible token field names from backend
        const token = json.authtoken || json.authToken || json.token;
        if (token) {
          localStorage.setItem("token", token);
          
          if (props.refreshAuthState) {
            props.refreshAuthState();
          }
          
          props.showAlert("Account created successfully! Welcome to Diary Desk!", "success");
          navigate("/");
        } else {
          console.error('No token received:', json);
          props.showAlert("Account created but no token received", "warning");
        }
      } else {
        // Handle various error message formats
        const errorMessage = json.error || json.message || json.errors || "Invalid details";
        props.showAlert(errorMessage, "danger");
      }
    } catch (error) {
      console.error('Signup error:', error);
      // More specific error handling
      if (error.message.includes('Failed to fetch')) {
        props.showAlert("Cannot connect to server. Please check if your backend is running on port 5000.", "danger");
      } else if (error.message.includes('HTTP error')) {
        props.showAlert("Server error. Please try again later.", "danger");
      } else {
        props.showAlert("Signup failed. Please try again.", "danger");
      }
    } finally {
      setLoading(false);
    }
  };

  const onChange = (e) => {
    setCredentials({ ...credentials, [e.target.name]: e.target.value });
  };

  return (
    <div className="container mt-4">
      <div className="row justify-content-center">
        <div className="col-md-6">
          <div className="card shadow">
            <div className="card-header text-center bg-success text-white">
              <h2 className="mb-0">
                <i className="fas fa-user-plus me-2"></i>Create Account
              </h2>
              <p className="mb-0 mt-2">Join Diary Desk today!</p>
            </div>
            <div className="card-body p-4">
              <form onSubmit={handleSubmit}>
                <div className="mb-3">
                  <label htmlFor="name" className="form-label">
                    <i className="fas fa-user me-2"></i>Full Name
                  </label>
                  <input
                    type="text"
                    className="form-control"
                    id="name"
                    name="name"
                    value={credentials.name}
                    onChange={onChange}
                    placeholder="Enter your full name"
                    required
                    minLength={3}
                  />
                  <div className="form-text">
                    {credentials.name.length > 0 && credentials.name.length < 3 && (
                      <span className="text-danger">Name must be at least 3 characters</span>
                    )}
                  </div>
                </div>

                <div className="mb-3">
                  <label htmlFor="email" className="form-label">
                    <i className="fas fa-envelope me-2"></i>Email address
                  </label>
                  <input
                    type="email"
                    className="form-control"
                    id="email"
                    name="email"
                    value={credentials.email}
                    onChange={onChange}
                    placeholder="Enter your email"
                    required
                  />
                  <div className="form-text">
                    We'll never share your email with anyone else.
                  </div>
                </div>

                <div className="mb-3">
                  <label htmlFor="password" className="form-label">
                    <i className="fas fa-lock me-2"></i>Password
                  </label>
                  <div className="position-relative">
                    <input
                      type={showPassword ? "text" : "password"}
                      className="form-control"
                      id="password"
                      name="password"
                      value={credentials.password}
                      onChange={onChange}
                      placeholder="Enter password (min 5 characters)"
                      minLength={5}
                      required
                    />
                    <button
                      type="button"
                      className="btn btn-outline-secondary position-absolute end-0 top-0 h-100"
                      onClick={() => setShowPassword(!showPassword)}
                      aria-label={showPassword ? "Hide password" : "Show password"}
                      style={{ zIndex: 10 }}
                    >
                      <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                    </button>
                  </div>
                  <div className="form-text">
                    {credentials.password.length > 0 && credentials.password.length < 5 && (
                      <span className="text-danger">Password must be at least 5 characters</span>
                    )}
                  </div>
                </div>

                <div className="mb-3">
                  <label htmlFor="cpassword" className="form-label">
                    <i className="fas fa-check-circle me-2"></i>Confirm Password
                  </label>
                  <div className="position-relative">
                    <input
                      type={showConfirmPassword ? "text" : "password"}
                      className="form-control"
                      id="cpassword"
                      name="cpassword"
                      value={credentials.cpassword}
                      onChange={onChange}
                      placeholder="Confirm your password"
                      minLength={5}
                      required
                    />
                    <button
                      type="button"
                      className="btn btn-outline-secondary position-absolute end-0 top-0 h-100"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      aria-label={showConfirmPassword ? "Hide password" : "Show password"}
                      style={{ zIndex: 10 }}
                    >
                      <i className={`fas ${showConfirmPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                    </button>
                  </div>
                  {/* Password Match Indicator */}
                  {credentials.password && credentials.cpassword && (
                    <div className="form-text">
                      {credentials.password === credentials.cpassword ? (
                        <span className="text-success">
                          <i className="fas fa-check me-1"></i>Passwords match
                        </span>
                      ) : (
                        <span className="text-danger">
                          <i className="fas fa-times me-1"></i>Passwords don't match
                        </span>
                      )}
                    </div>
                  )}
                </div>

                <div className="d-grid">
                  <button 
                    type="submit" 
                    className="btn btn-success btn-lg"
                    disabled={
                      loading || 
                      !credentials.name || 
                      !credentials.email || 
                      !credentials.password || 
                      !credentials.cpassword ||
                      credentials.password !== credentials.cpassword ||
                      credentials.password.length < 5 ||
                      credentials.name.length < 3
                    }
                  >
                    {loading ? (
                      <>
                        <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                        Creating Account...
                      </>
                    ) : (
                      <>
                        <i className="fas fa-user-plus me-2"></i>Create Account
                      </>
                    )}
                  </button>
                </div>
              </form>

              <div className="text-center mt-3">
                <p className="mb-0">
                  Already have an account? 
                  <Link to="/login" className="text-decoration-none ms-1">
                    <i className="fas fa-sign-in-alt me-1"></i>Login here
                  </Link>
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Signup;
